import { Router, Request, Response } from 'express';
import { testController } from '../controllers/test.controller';

/**
 * Test Routes
 * Endpoints for testing and debugging SQL generation pipeline
 */
const router = Router();

/**
 * POST /api/test/generate
 * Test SQL generation pipeline without executing the query
 * 
 * Returns:
 * 1. The prompt sent to LLM (with schema)
 * 2. The SQL generated by LLM (raw and cleaned)
 * 3. The validation result (valid/invalid with error messages)
 * 
 * Request Body:
 * {
 *   "question": string,
 *   "provider": "openrouter" | "ollama",
 *   "model": string
 * }
 * 
 * Response:
 * {
 *   "success": boolean,
 *   "test": {
 *     "question": string,
 *     "provider": string,
 *     "model": string
 *   },
 *   "step1_prompt": {
 *     "prompt": string,
 *     "length": number,
 *     "lines": number
 *   },
 *   "step2_sql_generated": {
 *     "raw": string,
 *     "cleaned": string,
 *     "generationTimeMs": number
 *   },
 *   "step3_validation": {
 *     "valid": boolean,
 *     "error": string,
 *     "warnings": string[]
 *   },
 *   "metadata": {
 *     "promptTokens": number,
 *     "completionTokens": number,
 *     "totalTokens": number,
 *     "responseTimeMs": number,
 *     "costEstimate": number
 *   }
 * }
 */
router.post('/generate', (req: Request, res: Response) => {
  testController.testGeneration(req, res);
});

export default router;
